const $=id=>document.getElementById(id), canvas=$('game'), ctx=canvas.getContext('2d');
let W=960,H=680,state='ready',held=false,y=340,vy=0,r=21,gates=[],score=0,best=0,clock=0,spawn=0,last=0,acc=0,seed=1,sound=true,audio=null,particles=[],diedAt=0;
try{best=Math.max(0,Number(localStorage.getItem('puff-best-v1'))||0)}catch{} $('best').textContent=String(best).padStart(2,'0');
function resize(){const box=canvas.getBoundingClientRect();const old=H;H=680;W=H*box.width/box.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(box.width*d);canvas.height=Math.round(box.height*d);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);if(old&&state==='playing')pause();}new ResizeObserver(resize).observe(canvas);
function rand(){seed=(Math.imul(1664525,seed)+1013904223)>>>0;return seed/4294967296}
function tone(freq,dur=.1){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.18,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
const palettes=[
{name:'Electric lagoon',top:'#14285b',bottom:'#087f96',gate:'#ff5da2',cap:'#ffb5db',ball:'#ffcd43',shine:'#fff3b0',accent:'#4bf2df'},
{name:'Sunset soda',top:'#541879',bottom:'#d74973',gate:'#36d5cd',cap:'#9ffff0',ball:'#ffe061',shine:'#fff8ca',accent:'#ffd166'},
{name:'Cosmic candy',top:'#221359',bottom:'#6139a1',gate:'#ffa444',cap:'#ffe0a1',ball:'#f56bd7',shine:'#ffd9f8',accent:'#71e6ff'},
{name:'Blue raspberry',top:'#102765',bottom:'#126fd1',gate:'#a7ed48',cap:'#e2ffac',ball:'#ff856a',shine:'#ffe6bd',accent:'#ffafd2'},
{name:'Mango sunset',top:'#782745',bottom:'#d9772a',gate:'#9169f8',cap:'#d6c4ff',ball:'#57f5d2',shine:'#d3fff4',accent:'#ffe175'},
{name:'Neon garden',top:'#103d56',bottom:'#147958',gate:'#ed70d4',cap:'#ffb9ea',ball:'#ffcb51',shine:'#fff3b9',accent:'#97efff'}];
const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches??false;
let deathAge=0,burstKind=0,burstX=0,burstY=0,deathMessage=null,messageBag=[],effectBag=[],countdown=0;
const failures=[['Pop goes the Puff!','That gap was playing hard to get.'],['Air today. Gone tomorrow.','A little less puff next time?'],['Well, that escalated.','Up was good. Too much up was ambitious.'],['A tiny pop. A big dream.','Your next great flight is one tap away.'],['Puff has left the chat.','Rejoining in three… two…'],['Too fabulous to fit.','Try shrinking before the next squeeze.'],['Gravity: 1. Puff: 0.','Time for a rematch.'],['Unexpected confetti!','We meant to do that. Probably.'],['A brief air-ruption.','Keep the dream inflated.'],['One puff too far.','So close. Shall we go again?']];
function pickBag(kind,total){let bag=kind==='message'?messageBag:effectBag;if(!bag.length){bag=Array.from({length:total},(_,i)=>i);for(let i=bag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}if(kind==='message')messageBag=bag;else effectBag=bag}return bag.pop()}
function theme(){return palettes[Math.floor(score/5)%palettes.length]}
function applyTheme(){const t=theme();document.documentElement.style.setProperty('--accent',t.accent);$('world').textContent=t.name;}
function soundLabel(){$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-label',sound?'Disable sound':'Enable sound');$('sound').setAttribute('aria-pressed',String(sound))}
function melody(notes){notes.forEach((n,i)=>setTimeout(()=>tone(n,.16),i*90))}
function levelBreak(){state='level';held=false;vy=0;show('Level '+Math.floor(score/5)+' cleared!',score+' gates in one flight. Next stop: '+theme().name+'.','Next level','KEEP THE FLIGHT ALIVE');$('levelAd').hidden=false;$('pause').disabled=true;melody([523,659,784,1047])}
function continueFlight(){state='countdown';held=false;countdown=1.5;$('overlay').hidden=true;$('levelAd').hidden=true;$('pause').disabled=true}
function updateHud(){applyTheme();$('score').textContent=String(score).padStart(2,'0');$('best').textContent=String(best).padStart(2,'0');$('level').textContent='LEVEL '+String(1+Math.floor(score/5)).padStart(2,'0');$('dots').textContent=Array.from({length:5},(_,i)=>i<=score%5?'●':'○').join(' ')}
function start(){state='playing';held=false;$('landingAd').hidden=true;$('levelAd').hidden=true;deathMessage=null;y=H/2;vy=0;r=21;score=0;clock=0;gates=[];particles=[];spawn=.65;seed=crypto.getRandomValues(new Uint32Array(1))[0];acc=0;$('overlay').hidden=true;$('pause').disabled=false;$('pause').textContent='Pause Ⅱ';$('status').textContent='Hold to rise · Release to fall';updateHud();tone(420)}
function show(title,message,button,pill){$('title').innerHTML=title;$('message').textContent=message;$('start').innerHTML=button+' <span>↗</span>';$('pill').textContent=pill;$('overlay').hidden=false;}
function die(){state='burst';held=false;deathAge=0;burstX=W*.26;burstY=y;burstKind=pickBag('effect',4);diedAt=performance.now();const isBest=score>best;if(isBest){best=score;try{localStorage.setItem('puff-best-v1',String(best))}catch{}}updateHud();const phrase=failures[pickBag('message',failures.length)];deathMessage={title:phrase[0],text:score+' gates cleared · '+phrase[1],pill:isBest?'NEW PERSONAL BEST!':'ONE MORE TRY?'};const colors=[theme().ball,theme().cap,theme().accent,'#ffffff','#ff65a8'];for(let i=0;i<(reduced?10:42);i++){const a=i/42*Math.PI*2,v=burstKind===2?140:110+Math.random()*190;particles.push({x:burstX,y:burstY,vx:Math.cos(a)*v,vy:Math.sin(a)*v-(burstKind===1?150:0),life:1.4,color:colors[i%colors.length],angle:a,size:4+Math.random()*5})}melody(burstKind===3?[440,330,165]:[260,110]);$('pause').disabled=true;$('status').textContent=phrase[1]}
function pause(){if(state!=='playing')return;state='paused';held=false;show('Take a<br>breather.','Your flight is waiting exactly where you left it.','Keep flying','PAUSED');$('pause').textContent='Resume ▷'}
function resume(){continueFlight();$('pause').textContent='Pause Ⅱ'}
$('start').onclick=()=>{if(state==='paused'||state==='level')resume();else start();$('start').blur()};$('pause').onclick=()=>state==='paused'?resume():pause();$('sound').onclick=()=>{sound=!sound;soundLabel();try{localStorage.setItem('puff-sound',String(sound))}catch{}if(sound)tone(650)};
try{sound=localStorage.getItem('puff-sound')!=='false'}catch{}soundLabel();

canvas.addEventListener('pointerdown',e=>{e.preventDefault();if(state==='over'&&performance.now()-diedAt>350)start();if(state==='playing'){held=true;canvas.setPointerCapture(e.pointerId)}});window.addEventListener('pointerup',()=>held=false);window.addEventListener('pointercancel',()=>held=false);window.addEventListener('blur',()=>{held=false;pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
window.addEventListener('keydown',e=>{if(e.code==='Escape'||e.code==='KeyP'){if(state==='playing')pause();else if(state==='paused')resume();return}if(e.code!=='Space'&&e.code!=='ArrowUp')return;if(e.target instanceof HTMLButtonElement)return;e.preventDefault();if(e.repeat)return;if(state==='ready'||state==='over'){start();held=true}else if(state==='paused'||state==='level')resume();else if(state==='playing')held=true});window.addEventListener('keyup',e=>{if(e.code==='Space'||e.code==='ArrowUp')held=false});
function tick(dt){particles=particles.filter(p=>p.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.angle+=dt*4;if(burstKind===1)p.vy+=400*dt}if(state==='burst'){deathAge+=dt;if(deathAge>=(reduced?.2:.75)){state='over';show(deathMessage.title,deathMessage.text,'Fly again',deathMessage.pill)}return}if(state==='countdown'){countdown-=dt;if(countdown<=0){state='playing';$('pause').disabled=false;tone(700)}return}if(state!=='playing')return;clock+=dt;const level=Math.floor(score/5);r+=((held?30:17)-r)*Math.min(1,dt*7);vy+=(held?-510:430)*dt;vy*=Math.exp(-1.8*dt);vy=Math.max(-190,Math.min(190,vy));y+=vy*dt;const speed=125+Math.min(level,12)*7;spawn-=dt;if(spawn<=0){const gap=230-Math.min(level,10)*7;const prev=gates.at(-1)?.center??H/2;const center=Math.max(175,Math.min(H-165,prev+(rand()-.5)*160));gates.push({x:W+50,center,gap,passed:false});spawn=2.2}const x=W*.26;if(y-r<86||y+r>H-55){die();return}for(const g of gates){g.x-=speed*dt;const nearX=Math.max(g.x,Math.min(x,g.x+49));const dx=x-nearX;const top=g.center-g.gap/2,bot=g.center+g.gap/2;if(dx*dx+Math.max(0,y-top)**2<r*r||dx*dx+Math.max(0,bot-y)**2<r*r){die();return}if(!g.passed&&g.x+49<x-r){g.passed=true;score++;updateHud();tone(score%5===0?900:610);$('status').textContent='Nice squeeze.';if(score%5===0){levelBreak();return}}}gates=gates.filter(g=>g.x>-70)}
function rect(x,y,w,h,rad,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,rad);ctx.fill()}
function draw(t){ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,0,H);const palette=theme();bg.addColorStop(0,palette.top);bg.addColorStop(1,palette.bottom);ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#ffffff06';ctx.lineWidth=1;for(let x=-(clock*15)%60;x<W;x+=60){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let yy=20;yy<H;yy+=60){ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(W,yy);ctx.stroke()}for(let i=0;i<25;i++){const px=((i*127.1-clock*16)%(W+60)+W+60)%(W+60)-30;ctx.fillStyle='#bfe6d522';ctx.beginPath();ctx.arc(px,110+(i*71)%470,i%3+1,0,Math.PI*2);ctx.fill()}
rect(0,79,W,3,0,'#7ca3a233');rect(0,H-52,W,3,0,'#7ca3a233');
for(const g of gates){const top=g.center-g.gap/2,bot=g.center+g.gap/2;rect(g.x,82,49,top-82,9,palette.gate);rect(g.x,bot,49,H-52-bot,9,palette.gate);rect(g.x+8,89,5,Math.max(0,top-100),3,'#ffffff55');rect(g.x+8,bot+10,5,Math.max(0,H-74-bot),3,'#ffffff55');rect(g.x-4,top-17,57,17,5,palette.cap);rect(g.x-4,bot,57,17,5,palette.cap)}
if(state!=='over'&&state!=='burst'){const px=W*.26,py=state==='ready'?H*.63+Math.sin(t/650)*12:y;ctx.save();ctx.translate(px,py);ctx.rotate(Math.max(-.18,Math.min(.18,vy/900)));ctx.shadowBlur=26;ctx.shadowColor='#d2ff7835';const grad=ctx.createRadialGradient(-r*.35,-r*.4,1,0,0,r*1.2);grad.addColorStop(0,palette.shine);grad.addColorStop(1,palette.ball);ctx.fillStyle=grad;ctx.beginPath();ctx.ellipse(0,0,r,r*1.06,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=palette.ball;ctx.beginPath();ctx.moveTo(0,r);ctx.lineTo(-4,r+7);ctx.lineTo(4,r+7);ctx.fill();ctx.strokeStyle='#a9c7ab';ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(0,r+7);ctx.bezierCurveTo(-9,r+17,8,r+25,-2,r+36);ctx.stroke();ctx.fillStyle='#233c33';for(const xx of [-6,7]){ctx.beginPath();ctx.ellipse(xx,-1,2.1,3,0,0,Math.PI*2);ctx.fill()}ctx.strokeStyle='#233c33';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(1,4,4,0,Math.PI);ctx.stroke();ctx.restore()}
for(const p of particles){ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,p.life));ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle=p.color;if(burstKind===0){ctx.beginPath();ctx.arc(0,0,p.size,0,Math.PI*2);ctx.fill()}else if(burstKind===3){ctx.beginPath();for(let j=0;j<10;j++){const a=j*Math.PI/5,rr=j%2?p.size*.4:p.size;ctx.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}ctx.closePath();ctx.fill()}else ctx.fillRect(-p.size/2,-p.size/2,p.size,burstKind===1?p.size*2:p.size);ctx.restore()}ctx.globalAlpha=1;if(state==='burst'&&burstKind===2&&!reduced){ctx.strokeStyle=palette.accent;ctx.lineWidth=5;ctx.globalAlpha=Math.max(0,1-deathAge);ctx.beginPath();ctx.arc(burstX,burstY,25+deathAge*180,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}if(state==='countdown'){ctx.fillStyle='#ffffff';ctx.font='bold 44px sans-serif';ctx.textAlign='center';ctx.fillText(countdown>.5?'Ready?':'Go!',W/2,H/2)}if(state==='playing'&&clock<3){ctx.fillStyle='#d4e4dfa0';ctx.font='14px sans-serif';ctx.textAlign='center';ctx.fillText(held?'Release to shrink ↓':'Hold to rise ↑',W*.26,Math.min(H-90,y+r+65))}}
function frame(t){const dt=Math.min((t-last)/1000||0,.05);last=t;acc+=dt;while(acc>=1/120){tick(1/120);acc-=1/120}draw(t);requestAnimationFrame(frame)}resize();requestAnimationFrame(frame);
const context=document.modelContext;if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'get_puff_run',description:'Read the current Puff run score, level, and device best.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({state,gatesCleared:score,level:1+Math.floor(score/5),deviceBest:best})})).catch(()=>{})}catch{}}
